```

**Do not use Werkzeug’s verifier for Argon2 hashes or compare the submitted password directly to `password_hash`.** The verifier must match the stored hash format.

## 3. Add the login form and authentication routes

Create `app/auth/routes.py`:

```python
from flask import (
    Blueprint,
    current_app,
    redirect,
    render_template,
    session,
    url_for,
)
from flask_login import (
    current_user,
    login_required,
    login_user,
    logout_user,
)
from flask_wtf import FlaskForm
from sqlalchemy.exc import SQLAlchemyError
from wtforms import PasswordField, StringField, SubmitField
from wtforms.validators import InputRequired, Length

from app import db, login_manager
from app.models import User

auth = Blueprint("auth", __name__)


class LoginForm(FlaskForm):
    username = StringField(
        "Username",
        validators=[InputRequired(), Length(max=80)],
    )
    password = PasswordField(
        "Password",
        validators=[InputRequired(), Length(max=1024)],
    )
    submit = SubmitField("Log in")


class LogoutForm(FlaskForm):
    submit = SubmitField("Log out")


@login_manager.user_loader
def load_user(user_id):
    try:
        user_id = int(user_id)
    except (TypeError, ValueError):
        return None

    return db.session.get(User, user_id)


@auth.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("auth.dashboard"))

    form = LoginForm()
    error = None

    if form.validate_on_submit():
        username = form.username.data.strip()
        password = form.password.data  # Do not strip passwords.

        try:
            user = db.session.execute(
                db.select(User).where(User.username == username)
            ).scalar_one_or_none()

            valid = user is not None and user.check_password(password)
        except SQLAlchemyError:
            db.session.rollback()
            current_app.logger.exception("Database error during login")
            return render_template(
                "login.html",
                form=form,
                error="Login is temporarily unavailable. Please try again.",
            ), 503

        if not valid:
            error = "Invalid username or password."
            return render_template(
                "login.html", form=form, error=error
            ), 401

        # Remove any previous session state before authenticating.
        session.clear()
        login_user(user, remember=False)
        session.permanent = True

        return redirect(url_for("auth.dashboard"))

    return render_template("login.html", form=form, error=error)


@auth.get("/dashboard")
@login_required
def dashboard():
    return render_template(
        "dashboard.html",
        logout_form=LogoutForm(),
    )


@auth.post("/logout")
@login_required
def logout():
    logout_user()
    session.clear()
    return redirect(url_for("auth.login"))
```

The 80-character username and 1,024-character password limits are example bounds; keep them consistent with your registration policy.

